<div>
    {{-- Banner --}}
    <section class="relative bg-gray-900 text-white flex items-center">
        <div class="absolute inset-0">
            <img src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee" alt="Banner"
                class="w-full h-full object-cover opacity-40" />
        </div>

        <div
            class="relative container mx-auto px-6 lg:px-8 py-12 md:py-24 flex flex-wrap items-center justify-between gap-8">
            <div class="max-w-3xl">
                <span class="inline-block px-4 py-2 rounded-full bg-indigo-600 text-sm font-medium">
                    New Collection
                </span>

                <h1 class="mt-6 text-5xl md:text-7xl font-bold leading-tight">
                    Build Beautiful Websites Faster
                </h1>

                <p class="mt-6 text-lg text-gray-300 max-w-2xl">
                    Create responsive, modern websites with reusable components and elegant
                    design powered by Tailwind CSS.
                </p>

                <div class="mt-10 flex gap-4">
                    <a href="#"
                        class="px-8 py-4 bg-indigo-600 hover:bg-indigo-700 rounded-lg font-semibold transition">
                        Get Started
                    </a>

                    <a href="#"
                        class="px-8 py-4 border border-white hover:bg-white hover:text-gray-900 rounded-lg font-semibold transition">
                        Learn More
                    </a>
                </div>
            </div>

            <div class="w-full md:w-md">
                <flux:card>
                    <div>
                        <flux:heading size="xl" class="font-serif">Request a callback</flux:heading>
                        <flux:text class="mt-1">Fill in your details and our team will contact you shortly.
                        </flux:text>
                    </div>
                    <flux:separator class="my-2" />
                    <form action="" class="space-y-4">
                        <flux:input label="Name" required />
                        <flux:input label="Email" required />
                        <flux:input label="Phone" required />
                        <flux:textarea label="Message" />
                        <flux:button type="submit" variant="primary" class="w-full">Send Enquiry</flux:button>
                    </form>
                </flux:card>
            </div>
        </div>
    </section>

